<script setup lang="ts">
import {computed,ref} from 'vue'
import {X} from 'lucide-vue-next'
import {useHysRootAttrs} from '../../config'
const props=defineProps<{modelValue:string;items:{label:string;value:string;disabled?:boolean;closable?:boolean}[];disabled?:boolean;type?:'line'|'card';vertical?:boolean;closable?:boolean;ariaLabel?:string}>()
const emit=defineEmits<{'update:modelValue':[value:string];change:[value:string];close:[value:string]}>(),root=ref<HTMLElement>(),hysRootAttrs=useHysRootAttrs()
const enabled=computed(()=>props.items.filter(x=>!props.disabled&&!x.disabled))
function select(value:string){if(!enabled.value.some(x=>x.value===value))return;const changed=value!==props.modelValue;emit('update:modelValue',value);if(changed)emit('change',value)}
function keyboard(event:KeyboardEvent){const keys=props.vertical?['ArrowUp','ArrowDown']:['ArrowLeft','ArrowRight'];if(![...keys,'Home','End'].includes(event.key)||!enabled.value.length)return;event.preventDefault();const index=enabled.value.findIndex(x=>x.value===props.modelValue),next=event.key==='Home'?0:event.key==='End'?enabled.value.length-1:index<0?(event.key===keys[0]?enabled.value.length-1:0):(index+(event.key===keys[0]?-1:1)+enabled.value.length)%enabled.value.length;select(enabled.value[next].value);const target=Array.from(root.value?.querySelectorAll<HTMLElement>('[role="tab"]')||[]).find(x=>x.dataset.tabValue===enabled.value[next].value);target?.focus()}
</script>
<template><div ref="root" v-bind="hysRootAttrs" class="hys-ui-tabs" :class="{'hys-ui-tabs-card':type==='card','hys-ui-tabs-vertical':vertical}" role="tablist" :aria-label="ariaLabel||'页签'" :aria-orientation="vertical?'vertical':'horizontal'" @keydown="keyboard"><div v-for="item in items" :key="item.value" class="hys-ui-tab-item"><button type="button" role="tab" :data-tab-value="item.value" :aria-selected="modelValue===item.value" :disabled="disabled||item.disabled" :tabindex="modelValue===item.value||(!enabled.some(x=>x.value===modelValue)&&enabled[0]?.value===item.value)?0:-1" :class="{'hys-ui-active':modelValue===item.value}" @click="select(item.value)"><slot name="label" :item="item">{{item.label}}</slot></button><button v-if="closable||item.closable" type="button" class="hys-ui-tab-close" :aria-label="'关闭'+item.label" :disabled="disabled||item.disabled" @click="emit('close',item.value)"><X :size="12"/></button></div></div><slot :active="modelValue"/></template>
<style scoped>.hys-ui-tabs{display:flex;overflow-x:auto}.hys-ui-tab-item{display:inline-flex;align-items:center;position:relative}.hys-ui-tab-close{padding:3px!important;border:0!important;background:transparent;color:inherit}.hys-ui-tabs-vertical{flex-direction:column;align-items:stretch}.hys-ui-tabs-card .hys-ui-tab-item{border:1px solid var(--hys-ui-border,var(--hys-ui-theme-border));border-radius:7px 7px 0 0;margin-right:4px}.hys-ui-tabs-card button.hys-ui-active{background:var(--hys-ui-primary-soft,var(--hys-ui-theme-primary-soft))}</style>
